// Extract message text and sender info from Evolution API payload
const body = $input.first().json.body || $input.first().json;
const data = body.data || {};
const key = data.key || {};
const message = data.message || {};
const pushName = data.pushName || 'User';

// Extract text from either conversation or extendedTextMessage
const messageText = message.conversation 
  || message.extendedTextMessage?.text 
  || '';

// Extract sender number from remoteJid (format: 5511999999999@s.whatsapp.net)
const remoteJid = key.remoteJid || '';
const senderNumber = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '');

if (!messageText) {
  // No text content (could be image, audio, etc.) - skip
  return [];
}

console.log('WA_MESSAGE_RECEIVED:', JSON.stringify({
  sender: senderNumber,
  pushName,
  messageLength: messageText.length,
  messageId: key.id,
  timestamp: new Date().toISOString()
}));

return {
  json: {
    senderNumber,
    remoteJid,
    pushName,
    messageText,
    messageId: key.id || '',
    timestamp: new Date().toISOString()
  }
};

// Build OpenAI-compatible payload for OpenClaw gateway (Claude Max)
const input = $input.first().json;
const userMessage = input.messageText;
const pushName = input.pushName;

return {
  json: {
    ...input,
    aiPayload: {
      model: 'moltbot',
      messages: [
        {
          role: 'system',
          content: 'You are a helpful AI assistant available via WhatsApp for a SCAD capstone book design project (TheGreatBook). Keep responses concise (under 800 chars) since this is a chat medium. Be friendly, supportive, and helpful with design, Adobe InDesign, layout, and creative project questions.'
        },
        {
          role: 'user',
          content: pushName + ': ' + userMessage
        }
      ],
      stream: false
    }
  }
};

// Parse OpenAI-compatible response from OpenClaw gateway
const aiResponse = $input.first().json;
const messageCtx = $('Extract Message').first().json;

let responseText = '';

if (aiResponse.error || !aiResponse.choices || !aiResponse.choices[0]) {
  console.log('AI_ERROR:', JSON.stringify({
    error: aiResponse.error || 'No choices in response',
    sender: messageCtx.senderNumber
  }));
  responseText = 'Sorry, I\'m having trouble right now. Please try again in a moment.';
} else {
  responseText = aiResponse.choices[0].message.content.trim();
}

if (responseText.length > 1500) {
  responseText = responseText.substring(0, 1497) + '...';
}

return {
  json: {
    number: messageCtx.senderNumber,
    text: responseText,
    senderName: messageCtx.pushName,
    messageId: messageCtx.messageId
  }
};

// Log successful send and return confirmation
const sendResult = $input.first().json;
const messageCtx = $('Extract Message').first().json;

console.log('WA_REPLY_SENT:', JSON.stringify({
  sender: messageCtx.senderNumber,
  pushName: messageCtx.pushName,
  messageId: messageCtx.messageId,
  sendStatus: sendResult.status || 'sent',
  timestamp: new Date().toISOString()
}));

return {
  json: {
    status: 'ok',
    message: 'Reply sent successfully',
    to: messageCtx.senderNumber,
    timestamp: new Date().toISOString()
  }
};

// Non-qualifying event (outgoing message, status update, etc.) - drop silently
console.log('WA_FILTERED_OUT:', JSON.stringify({
  event: $input.first().json.body?.event || 'unknown',
  fromMe: $input.first().json.body?.data?.key?.fromMe,
  timestamp: new Date().toISOString()
}));

return {
  json: {
    status: 'filtered',
    reason: 'Not an incoming user message'
  }
};
